const sheets = [
  "March2025", "April2025", "May2025", "June2025", "July2025", "August2025",
  "September2025", "October2025", "Nocember2025", "December2025", "January2026", "February2026",
  "March2026", "April2026", "May2026", "June2026", "July2026", "August2026",
  "September2026", "Octobe2026"
];

const fileBinary = $input.first().binary;

return sheets.map(name => ({
  json: { sheetName: name },
  binary: fileBinary
}));

const items = $input.all();

const sheets = [
  "March2025", "April2025", "May2025", "June2025", "July2025", "August2025",
  "September2025", "October2025", "Nocember 2025", "December2025", "January2026", "February2026",
  "March2026", "April2026", "May2026", "June2026", "July2026", "August2026",
  "Septembe2026", "Octobe2026"
];

const memberStats = {};
const monthlyStats = {};
let totalLunch = 0;
let totalDinner = 0;
let totalGuestMeals = 0;
let activeDaysCount = 0;
let zeroMealDaysCount = 0;

for (const item of items) {
  const row = item.json;
  const keys = Object.keys(row);
  if (keys.length === 0) continue;

  // Identify which of the 20 sheets this row came from
  const sheetIdx = item.pairedItem?.item ?? 0;
  const monthName = sheets[sheetIdx] || `Sheet_${sheetIdx + 1}`;

  // Pair each Member column (Lunch) with the following __EMPTY column (Dinner)
  const pairs = [];
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    if (!key.startsWith("__EMPTY")) {
      const nextKey = keys[i + 1] && keys[i + 1].startsWith("__EMPTY") ? keys[i + 1] : null;
      pairs.push({ member: key.trim(), lunchKey: key, dinnerKey: nextKey });
    }
  }

  // Skip text sub-headers (e.g., "Lunch"/"Dinner") or bottom "Total" summary rows (>10 meals in 1 slot)
  let isSummaryOrHeaderRow = false;
  let rowMealsTotal = 0;

  for (const p of pairs) {
    const lVal = row[p.lunchKey];
    const dVal = p.dinnerKey ? row[p.dinnerKey] : 0;

    if (typeof lVal === "string" && isNaN(Number(lVal))) isSummaryOrHeaderRow = true;
    if (typeof dVal === "string" && isNaN(Number(dVal))) isSummaryOrHeaderRow = true;

    const lNum = Number(lVal) || 0;
    const dNum = Number(dVal) || 0;

    // A single person doesn't eat >10 lunches in one day; that indicates a monthly sum row
    if (lNum > 10 || dNum > 10 || lNum < 0 || dNum < 0) {
      isSummaryOrHeaderRow = true;
    }
    rowMealsTotal += lNum + dNum;
  }

  if (isSummaryOrHeaderRow) continue;

  if (rowMealsTotal === 0) {
    zeroMealDaysCount++;
  } else {
    activeDaysCount++;
  }

  if (!monthlyStats[monthName]) {
    monthlyStats[monthName] = { lunch: 0, dinner: 0, total: 0, active_days: 0 };
  }
  if (rowMealsTotal > 0) monthlyStats[monthName].active_days++;

  // Accumulate Lunch, Dinner, and Guest Meals per member and per month
  for (const p of pairs) {
    const lunch = Number(row[p.lunchKey]) || 0;
    const dinner = p.dinnerKey ? (Number(row[p.dinnerKey]) || 0) : 0;

    if (!memberStats[p.member]) {
      memberStats[p.member] = {
        lunch: 0,
        dinner: 0,
        total_meals: 0,
        guest_meals: 0,
        lunch_skipped_days: 0,
        dinner_skipped_days: 0
      };
    }

    memberStats[p.member].lunch += lunch;
    memberStats[p.member].dinner += dinner;
    memberStats[p.member].total_meals += lunch + dinner;

    // Count guest meals (when a member takes >1 meal in a single Lunch or Dinner slot)
    const guestInSlot = Math.max(0, lunch - 1) + Math.max(0, dinner - 1);
    memberStats[p.member].guest_meals += guestInSlot;
    totalGuestMeals += guestInSlot;

    if (rowMealsTotal > 0) {
      if (lunch === 0) memberStats[p.member].lunch_skipped_days++;
      if (dinner === 0) memberStats[p.member].dinner_skipped_days++;
    }

    monthlyStats[monthName].lunch += lunch;
    monthlyStats[monthName].dinner += dinner;
    monthlyStats[monthName].total += lunch + dinner;

    totalLunch += lunch;
    totalDinner += dinner;
  }
}

return [{
  json: {
    report_period: "March 2025 - October 2026 (20 Months)",
    overall_summary: {
      total_meals_served: totalLunch + totalDinner,
      total_lunch_served: totalLunch,
      total_dinner_served: totalDinner,
      lunch_vs_dinner_ratio: `${ ((totalLunch / Math.max(1, totalLunch + totalDinner)) * 100).toFixed(1) }% Lunch / ${ ((totalDinner / Math.max(1, totalLunch + totalDinner)) * 100).toFixed(1) }% Dinner`,
      total_guest_meals: totalGuestMeals,
      active_hostel_days: activeDaysCount,
      zero_meal_closed_days: zeroMealDaysCount
    },
    member_breakdown: memberStats,
    monthly_breakdown: monthlyStats
  }
}];
